+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * @param name     free text; every whitespace-separated term must appear in the
+ *                 first or last name, ignoring case and accents. Blank matches all.
+ * @param statuses statuses to include; empty matches all
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** A filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The normalized search terms of {@link #name()}. */
+    public List<String> terms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(name.split("\\s+"))
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::normalize)
+                .toList();
+    }
+
+    /** Folds case and strips accents, so that "Mäkinen" becomes "makinen". */
+    public static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
